for n in [0, 1, 4]:
    sequential = 0
    for i in range(n):
        sequential = sequential + 1
    for j in range(n):
        sequential = sequential + 1

    rectangular = 0
    triangular = 0
    for i in range(n):
        for j in range(n):
            rectangular = rectangular + 1
        for j in range(i):
            triangular = triangular + 1
    print(n, sequential, rectangular, triangular)

def matching_pairs_with_cost(left, right):
    matches = 0
    comparisons = 0
    for a in left:
        for b in right:
            comparisons += 1
            if a == b:
                matches += 1
    return matches, comparisons

print(matching_pairs_with_cost([], [1]))
print(matching_pairs_with_cost([2, 2], [2, 3, 2]))
print(matching_pairs_with_cost([1], [9]))

def earlier_pairs(n):
    result = []
    for i in range(n):
        for j in range(i):
            result.append((j, i))
    return result

print(earlier_pairs(0))
print(earlier_pairs(1))
print(earlier_pairs(3))
